import {createPlan, validateState, progress} from './core.mjs';
const key='clearstudy-v1', $=s=>document.querySelector(s);
const example=()=>({version:1,minutes:45,topics:[{id:'bell',title:'Bell states and entanglement',importance:3,confidence:1},{id:'gates',title:'Quantum gates',importance:3,confidence:2},{id:'measurement',title:'Measurement probabilities',importance:2,confidence:2}],plan:null});
let state=example(), storageAvailable=true;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){$('#message').textContent=message;}
try {const saved=localStorage.getItem(key);if(saved) state=validateState(JSON.parse(saved));} catch {notify('Your previous plan could not be restored. An example is ready; your original backup file has not changed.');}
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{storageAvailable=false;notify('Browser storage is unavailable. Download a backup before leaving this page.');}}
function form(){
 $('#minutes').value=state.minutes;
 $('#topics').innerHTML=state.topics.map((t,i)=>`<div class="topic" data-id="${escape(t.id)}"><div class="topic-name"><label for="title-${i}">Topic ${i+1}<input id="title-${i}" name="title" value="${escape(t.title)}" maxlength="120" required></label><button class="remove" type="button" data-remove="${i}" aria-label="Remove topic ${i+1}" ${state.topics.length===1?'disabled':''}>×</button></div><div class="topic-options"><label for="importance-${i}">Importance<select id="importance-${i}" name="importance">${options(t.importance,['Useful','Important','Essential'])}</select></label><label for="confidence-${i}">How well do you know it?<select id="confidence-${i}" name="confidence">${options(t.confidence,['Need help','Getting there','Confident'])}</select></label></div></div>`).join('');
 $('#add').disabled=state.topics.length>=20;
}
function options(value,labels){return labels.map((label,i)=>`<option value="${i+1}" ${value===i+1?'selected':''}>${label}</option>`).join('');}
function readForm(){state.minutes=Number($('#minutes').value);state.topics=[...document.querySelectorAll('.topic')].map(el=>({id:el.dataset.id,title:el.querySelector('[name=title]').value,importance:Number(el.querySelector('[name=importance]').value),confidence:Number(el.querySelector('[name=confidence]').value)}));}
function result(){
 if(!state.plan){$('#result').innerHTML='<div class="empty"><div class="empty-icon" aria-hidden="true">↗</div><h3>Your next step starts here.</h3><p>Choose your topics and time. Then make a plan that fits.</p></div>';return;}
 const p=progress(state.plan);
 $('#result').innerHTML=`<div class="summary"><span>${state.plan.minutes} minutes · ${p.total} topics</span><span>${p.done} of ${p.total} complete</span></div><progress value="${p.done}" max="${p.total}" aria-label="Topics completed"></progress>${state.plan.sessions.map((s,i)=>`<article class="session ${s.completed?'done':''}"><div class="session-top"><h3>${i+1}. ${escape(s.title)}</h3><span class="duration">${s.minutes} min</span></div><p class="reason">${escape(s.reason)}</p><ol class="recall"><li>Read your notes and find the main idea.</li><li>Close the notes. Explain the steps from memory.</li><li>Check one example and correct what you missed.</li></ol><label for="notes-${i}">One thing to remember<textarea id="notes-${i}" data-note="${i}" maxlength="3000" placeholder="Write it in your own words…">${escape(s.notes)}</textarea></label><button type="button" data-complete="${i}">${s.completed?'Mark as unfinished':'Mark topic complete'}</button></article>`).join('')}${state.plan.deferred.length?`<p class="deferred"><strong>For another session:</strong> ${state.plan.deferred.map(escape).join(', ')}. This window fits only ${p.total} topics at five minutes or more each.</p>`:''}<p class="hint">This is a suggested allocation. Completion means you checked the topic, not that mastery was measured.</p>`;
}
$('#planner').addEventListener('submit',e=>{e.preventDefault();readForm();try{state.plan=createPlan(state.topics,state.minutes);save();result();notify('Your plan is ready. Start with the first topic.');$('#plan-heading').setAttribute('tabindex','-1');$('#plan-heading').focus();}catch(err){notify(err.message);}});
$('#add').addEventListener('click',()=>{readForm();state.topics.push({id:crypto.randomUUID(),title:'',importance:2,confidence:1});state.plan=null;form();result();document.querySelectorAll('[name=title]')[state.topics.length-1].focus();});
$('#topics').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;readForm();state.topics.splice(Number(b.dataset.remove),1);state.plan=null;form();result();save();notify('Topic removed. Make a new plan when you are ready.');});
$('#planner').addEventListener('change',()=>{readForm();state.plan=null;result();try{validateState(state);save();notify('Topics changed. Make a new plan to apply them.');}catch{notify('Complete the topic names and time to save your changes.');}});
$('#result').addEventListener('click',e=>{const b=e.target.closest('[data-complete]');if(!b)return;const i=Number(b.dataset.complete);state.plan.sessions[i].completed=!state.plan.sessions[i].completed;save();result();document.querySelector(`[data-complete="${i}"]`).focus();notify(state.plan.sessions[i].completed?'Topic complete. Keep going at your own pace.':'Topic marked unfinished.');});
$('#result').addEventListener('input',e=>{if(e.target.dataset.note!==undefined){state.plan.sessions[Number(e.target.dataset.note)].notes=e.target.value;save();}});
$('#export').addEventListener('click',()=>{try{readForm();validateState(state);const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='clearstudy-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup downloaded. Keep it private if it contains personal notes.');}catch(err){notify(err.message);}});
$('#import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw new Error('Choose a backup smaller than 100 KB.');const restored=validateState(JSON.parse(await file.text()));state=restored;save();form();result();notify('Backup restored. Your saved progress is ready.');}catch(err){notify(`Backup not restored: ${err.message}`);}e.target.value='';});
$('#example').addEventListener('click',()=>{if(!confirm('Replace this browser’s plan with the example? Download a backup first if you need it.'))return;state=example();save();form();result();notify('A new example is ready.');});
form();result();
